2	import java.util.HashMap;
3	import java.util.Iterator;
4	import java.util.List;
5	
6	/**
7	 * A class representing shared characteristics of animals.
8	 *
9	 * @version 2022.03.01
10	 */
11	public abstract class Animal extends Actor
12	{
13	    private double foodLevel;
14	    private boolean isGirl;
15	    private boolean isHealthy;
16	    //the number of steps an animal takes when infected.
17	    private int infectedStepCounter;
18	    //how many steps animal needs to wait before it can breed again.
19	    private int timeLeftUntilBreedingAgain = 0;
20	    /**
21	     * Create a new animal at location in field.
22	     * 
23	     * @param field The field currently occupied.
24	     * @param location The location within the field.
25	     */
26	    public Animal(Field field, Location location)
27	    {
28	        super(field,location);
29	        setRandomGender();
30	        isHealthy = true;
31	        infectedStepCounter = 0;
32	        timeLeftUntilBreedingAgain= getRandom().nextInt(getMaxTimeUntilBreedingAgain());
33	        if(!isGirl){
34	        timeLeftUntilBreedingAgain = 0;
35	        }
36	    }
37	
38	    /**
39	     * Make this animal act - that is: make it do
40	     * whatever it wants/needs to do.
41	     * @param newActors A list to receive newly born animals.
42	     * @param simulator The simulator.
43	     */
44	    public void act(List<Actor> newActors, Simulator simulator) {
45	        setGrowthLevel(getGrowthRate());
46	        if(simulator.isDay()) {
47	            incrementAge(simulator.getSteps());
48	            incrementHunger();
49	            if(isActive()) {
50	                giveBirth(newActors);
51	                Location newLocation = findFood(getFoodProbability(simulator.getWeather()));
52	                if(newLocation == null) {
53	                    newLocation = getField().freeAdjacentLocation(getLocation());
54	                }
55	                if(newLocation != null) {
56	                    setLocation(newLocation);
57	                } else {
58	                    setDead();
59	                }
60	            }
61	        }
62	    }
63	
64	    abstract protected double getGrowthRate();
65	
66	    abstract protected double getFoodProbability(Weather weather);
67	
68	    /**
69	     * An animal can breed if it has reached the breeding age.
70	     * @return true if an animal is able to breed
71	     */
72	    protected boolean canBreed()
73	    {
74	        return getAge() >= getBreedingAge();
75	    }
76	
77	    /**
78	     * Get breeding age of an animal.
79	     * @return int. Breeding age of the animal;
80	     */
81	    abstract protected int getBreedingAge();
82	
83	    /**
84	     * Check whether or not this animal is to give birth at this step.
85	     * New births will be made into free adjacent locations.
86	     * @param newAnimals A list to return newly born animals.
87	     */
88	    protected void giveBirth(List<Actor> newAnimals)
89	    {
90	        // New animals are born into adjacent locations.
91	        // Get a list of adjacent free locations.
92	        Field field = getField();
93	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
94	        if (timeLeftUntilBreedingAgain != 0){
95	            timeLeftUntilBreedingAgain --;
96	        }
97	        int births = breed();
98	        for(int b = 0; b < births && free.size() > 0; b++) {
99	            Location loc = free.remove(0);
100	            Animal baby = createOffspring(field, loc);
101	            if(!getHealth()){
102	                baby.setUnhealthy();
103	            }
104	            newAnimals.add(baby);
105	        }
106	    }
107	
108	    abstract protected Animal createOffspring(Field field, Location location);
109	
110	    /**
111	     * Generate a number representing the number of births,
112	     * if it can breed.
113	     * Females can mate with a male even  regardless of the males breeding time .
114	     * @return The number of births (may be zero).
115	     */
116	    protected int breed()
117	    {
118	        int births = 0;
119	        if(canBreed()  && findMate() && getRandom().nextDouble() <= getBreedingProbability() && timeLeftUntilBreedingAgain == 0) {
120	            births = getRandom().nextInt(getMaxLitterSize()) + 1;
121	            timeLeftUntilBreedingAgain = getMaxTimeUntilBreedingAgain();
122	        }
123	        return births;
124	    }
125	
126	    /**
127	     * If the animal can find a mate of the opposite gender that can breed, true is returned.
128	     * @return true if the animal can find a mate.
129	     */
130	    protected boolean findMate()
131	    {
132	        Field field = getField();
133	        List<Location> adjacent = field.adjacentLocations(getLocation());
134	        Iterator<Location> it = adjacent.iterator();
135	        while(it.hasNext()) {
136	            Location where = it.next();
137	            Object animal = field.getObjectAt(where);
138	            if (animal != null && animal.getClass() == this.getClass()){
139	                Animal mate = (Animal) animal;
140	                if(isActive() && getIsGirl() && !mate.getIsGirl() && mate.canBreed()){
141	                    if(!getHealth() || !mate.getHealth()){
142	                        setUnhealthy();
143	                        mate.setUnhealthy();
144	                    }
145	                    return true;
146	                }
147	            }
148	        }
149	        return false;
150	    }
151	
152	    /**
153	     * Returns the breeding probability of the animal
154	     * @return breeding probability of the animal.
155	     */
156	    abstract protected double getBreedingProbability();
157	
158	    /**
159	     * Returns the maximum number of babies the animal can give birth to at once.
160	     * @return max litter size of the animal.
161	     */
162	    abstract protected int getMaxLitterSize();
163	
164	    /**
165	     * Returns the animal's current food level.
166	     * @return the animal's food level.
167	     */
168	    protected double getFoodLevel(){
169	        return foodLevel;
170	    }
171	
172	    /**
173	     * Sets the animal's food level.
174	     * @param foodlevel The new food level.
175	     */
176	    protected void setFoodLevel(double foodlevel){
177	        this.foodLevel = foodlevel;
178	    }
179	
180	    /**
181	     * Make this animal more hungry. This could result in the animal's death.
182	     */
183	    protected void incrementHunger()
184	    {
185	        foodLevel--;
186	        if(foodLevel <= 0) {
187	            setDead();
188	        }
189	    }
190	
191	    /**
192	     * Look for preys adjacent to the current location.
193	     * Only the first live prey is eaten.
194	     * @param probability The probability the animal finds prey.
195	     * @return Where food was found, or null if it wasn't.
196	     */
197	    protected Location findFood(double probability)
198	    {
199	
200	        Field field = getField();
201	        List<Location> adjacent = field.adjacentLocations(getLocation());
202	        Iterator<Location> it = adjacent.iterator();
203	
204	        if(getRandom().nextDouble() < probability && getFoodLevel() < getMaxFoodLevel()){
205	            while(it.hasNext()) {
206	                Location where = it.next();
207	                Object animal = field.getObjectAt(where);
208	                if(animal instanceof Actor){
209	                    Actor currentAnimal = (Actor) animal;
210	                    Integer foodValue = getFood().get(currentAnimal.getClass());
211	                    if(foodValue != null){
212	                        if (currentAnimal instanceof Animal){
213	                            Animal current = (Animal)currentAnimal;
214	                            if(!current.getHealth()){
215	                                setUnhealthy();
216	                            }
217	                        }
218	                        currentAnimal.setDead();
219	                        setFoodLevel(Math.min(getFoodLevel() + foodValue + currentAnimal.getGrowthLevel(), getMaxFoodLevel()));
220	                        return where;
221	                    }
222	                }
223	            }
224	        }
225	        return null;
226	    }
227	
228	    /**
229	     * Returns the HashMap which maps prey class types to their food values.
230	     * @return The HashMap which maps Class to food value Integer.
231	     */
232	    abstract protected HashMap<Class<? extends Actor>, Integer> getFood();
233	
234	    /**
235	     * Uses a random generator to assign if the animal is female or not.
236	     * @return True if the animal is a female.
237	     */
238	    protected void setRandomGender(){
239	        isGirl = getRandom().nextDouble() > 0.5;
240	    }
241	
242	    /**
243	     * Returns true if the animal is a female.
244	     * @return boolean. True if the animal is a female.
245	     */
246	    protected boolean getIsGirl(){
247	        return isGirl;
248	    }
249	
250	    /**
251	     * The animal has been infected.
252	     */
253	    protected void setUnhealthy(){
254	        isHealthy = false;
255	    }
256	
257	    /**
258	     * Returns whether the animal is healthy or not.
259	     * @return true if the animal is healthy.
260	     */
261	    protected boolean getHealth(){
262	        return isHealthy;
263	    }
264	
265	    /**
266	     * Increase the age. This could result in the animal's death.
267	     * If the animal is unhealthy it also increases the infected step counter.
268	     * After 5 steps inthe infectedStepCounter this may result in the animal's death.
269	     * @param step. The number of steps in the simulation.
270	     */
271	    protected void incrementAge(int step)
272	    {
273	        super.incrementAge(step);
274	        if(!getHealth()){
275	            infectedStepCounter++;}
276	
277	        if(infectedStepCounter == 5) {
278	            setDead();
279	        }
280	    }
281	
282	    /**
283	     * Gets the max food level of an animal.
284	     * @return Maximum food level of the current animal.
285	     */
286	    abstract protected double getMaxFoodLevel();
287	
288	    /**
289	     * Gets the max time an animal needs to wait before it can breed again.
290	     * @return Maximum time the animal waits before it can breed again.
291	     */
292	    abstract protected int getMaxTimeUntilBreedingAgain();
293	
294	}
