1	import java.util.Iterator;
2	import java.util.List;
3	
4	/**
5	 * A class representing additional characteristics for predators.
6	 * Inlucdes an additional method for carnivores which allow them to step
7	 * on the grass without eating it.
8	 *
9	 * @version 2022.03.01
10	 */
11	public abstract class Predator extends Animal
12	{
13	
14	    /**
15	     * Create a new predator at location in field.
16	     * 
17	     * @param field The field currently occupied.
18	     * @param location The location within the field.
19	     *
20	     */public Predator(Field field, Location location){
21	        super(field, location);
22	    }
23	
24	    /**
25	     * Hunts for prey in adjacent cells. If prey is found, returns its location.
26	     * If no prey is found, returns the location of the nearest plant to stand on (without eating it).
27	     * @param probability The probability the animal finds prey.
28	     * @return Where to move, or null if nowhere suitable was found.
29	     */
30	    protected Location findFood(double probability)
31	    {
32	        Location preyLocation = super.findFood(probability);
33	        if(preyLocation != null) {
34	            return preyLocation;
35	        }
36	        Field field = getField();
37	        List<Location> adjacent = field.adjacentLocations(getLocation());
38	        Iterator<Location> it = adjacent.iterator();
39	        while(it.hasNext()) {
40	            Location where = it.next();
41	            Object actor = field.getObjectAt(where);
42	            if(actor instanceof Plants){
43	                return where;
44	            }
45	        }
46	        return null;
47	    }
48	}
