2	import java.util.Arrays;
3	import java.util.HashSet;
4	import java.util.Iterator;
5	import java.util.List;
6	import java.util.Set;
7	
8	/**
9	 * A simple model of a Hunter.
10	 * Hunters age, move, hunt lions, and die.
11	 * Hunters can bring other hunters after 898 steps to increse the hunter population.
12	 *
13	 * @version 2022.03.01
14	 */
15	public class Hunter extends Actor
16	
17	{
18	    // Characteristics shared by all Hunters.
19	    private static final int MAX_AGE = 1000;
20	    private static final int SHOTS = 2;
21	    private static final Set<Class<? extends Actor>> HUNTABLE_SPECIES = new HashSet<>(Arrays.asList(Lion.class, Cheetah.class));
22	    /**
23	     * Create a Hunter. A hunter is created as an adult (age 50).
24	     * 
25	     * @param field The field currently occupied.
26	     * @param location The location within the field.
27	     */
28	    public Hunter(Field field, Location location)
29	    {
30	        super(field, location);
31	        setAge(50);
32	        setGrowthLevel(0);
33	    }
34	
35	    /**
36	     * This is what the Hunter does most of the time: it hunts
37	     * lions during the night. In the process, it might die of old age.
38	     * 
39	     * @param newHunters A list to return new Hunters.
40	     * @param simulator The simulator.
41	     */
42	    public void act(List<Actor> newHunters,Simulator simulator){
43	        incrementAge(simulator.getSteps());
44	        if(!simulator.isDay()){
45	            if(isActive() ) {
46	                switch(simulator.getWeather()){
47	                    case RAINY:
48	                        hunt(0.7);
49	                        break;
50	                    case FOGGY:
51	                        hunt(0.4);
52	                        break;
53	                    default:
54	                        hunt(getRandom().nextDouble());
55	                        break;
56	                }
57	                Field field = getField();
58	                Location newLocation = field.freeAdjacentLocation(getLocation());
59	                if(newLocation != null) {
60	                    setLocation(newLocation);
61	                } 
62	                //hunter number increases as there are more hunters in the area who want to hunt.
63	                if (simulator.getSteps() % 898 ==  0){
64	                    List<Location> free = field.getFreeAdjacentLocations(getLocation());
65	                    if(free.size() > 0) {
66	                        Location loc = free.remove(0);
67	                        Hunter hunter = new Hunter(field, loc);
68	                        newHunters.add(hunter);
69	                    }
70	                }
71	            }
72	        }
73	    }
74	
75	    /**
76	     * This determine how the hunter hunts nearby lions
77	     * The hunter has 2 shots.
78	     * @param probability The probability the hunting is successful.
79	     */
80	    private void hunt(double probability){
81	        if(getRandom().nextDouble() < probability){
82	            Field field = getField();
83	            List<Location> adjacent = field.adjacentLocations(getLocation());
84	            Iterator<Location> it = adjacent.iterator();
85	            for(int i = 0; i< SHOTS; i++){
86	                Location where = it.next();
87	                Object animal = field.getObjectAt(where);
88	                if(animal != null && HUNTABLE_SPECIES.contains(animal.getClass())){
89	                    Animal currentAnimal = (Animal) animal;
90	                    if(currentAnimal.isActive()) { 
91	                        currentAnimal.setDead();
92	                        break;
93	                    }
94	                }
95	            }
96	        }
97	    }
98	
99	    /**
100	     * Gets the max age of a hunter.
101	     * @return int. Max age of the hunter.
102	     */
103	    protected int getMaxAge(){
104	        return MAX_AGE;
105	    }
106	}
