1	import java.util.HashMap;
2	
3	/**
4	 * A simple model of a Gazelle.
5	 * Gazelles age, move, eat grass, breed, and die.
6	 *
7	 * @version 2022.03.01
8	 */
9	public class Gazelle extends Animal
10	{
11	    // Characteristics shared by all Gazelles (class variables).
12	
13	    // The age at which a Gazelle can start to breed.
14	    private static final int BREEDING_AGE = 2;
15	    // The age to which a Gazelle can live.
16	    private static final int MAX_AGE = 80;
17	    // The likelihood of a Gazelle breeding.
18	    private static final double BREEDING_PROBABILITY = 0.8900995;
19	    // The maximum number of births.
20	    private static final int MAX_LITTER_SIZE = 7;
21	    private static final int MAX_TIME_UNTIL_BREEDING_AGAIN = 2;
22	    private static final int GRASS_FOOD_VALUE = 14;
23	    private static final double MAX_FOOD_LEVEL = 28;
24	    private static final double GROWTH_RATE = 0.012;
25	
26	    // Individual characteristics (instance fields).
27	    private HashMap<Class<? extends Actor>, Integer> food;
28	
29	    /**
30	     * Create a new Gazelle. A Gazelle may be created with age
31	     * zero (a new born) or with a random age.
32	     *
33	     * @param randomAge If true, the Gazelle will have a random age.
34	     * @param field The field currently occupied.
35	     * @param location The location within the field.
36	     */
37	    public Gazelle(boolean randomAge, Field field, Location location)
38	    {
39	        super(field, location);
40	        if(randomAge) {
41	            setAge(getRandom().nextInt(MAX_AGE));
42	            setFoodLevel(getRandom().nextInt(GRASS_FOOD_VALUE));
43	        } else {
44	            setAge(0);
45	            setFoodLevel(GRASS_FOOD_VALUE);
46	        }
47	        food = new HashMap<>();
48	        setGrowthLevel(getAge()/75.0);
49	        addFood();
50	    }
51	
52	    protected double getGrowthRate() { return GROWTH_RATE; }
53	
54	    protected double getFoodProbability(Weather weather) {
55	        return 1.0;
56	    }
57	
58	    protected int getMaxLitterSize() { return MAX_LITTER_SIZE; }
59	
60	    protected double getBreedingProbability() { return BREEDING_PROBABILITY; }
61	
62	    protected int getBreedingAge() { return BREEDING_AGE; }
63	
64	    protected int getMaxAge() { return MAX_AGE; }
65	
66	    protected int getMaxTimeUntilBreedingAgain() { return MAX_TIME_UNTIL_BREEDING_AGAIN; }
67	
68	    protected Animal createOffspring(Field field, Location location) {
69	        return new Gazelle(false, field, location);
70	    }
71	
72	    private void addFood() {
73	        food.put(Grass.class, GRASS_FOOD_VALUE);
74	    }
75	
76	    protected HashMap<Class<? extends Actor>, Integer> getFood() { return food; }
77	
78	    protected double getMaxFoodLevel() { return MAX_FOOD_LEVEL; }
79	}
