1	import java.util.HashMap;
2	
3	/**
4	 * A simple model of a Zebra.
5	 * Zebras age, move, eat grass, breed, and die.
6	 *
7	 * @version 2022.03.01
8	 */
9	public class Zebra extends Animal
10	{
11	    // Characteristics shared by all Zebra (class variables).
12	
13	    // The age at which a Zebra can start to breed.
14	    private static final int BREEDING_AGE = 2;
15	    // The age to which a Zebra can live.
16	    private static final int MAX_AGE = 160;
17	    // The likelihood of a Zebra breeding.
18	    private static final double BREEDING_PROBABILITY = 0.27587999058995;
19	    // The maximum number of births.
20	    private static final int MAX_LITTER_SIZE = 4;
21	    private static final int MAX_TIME_UNTIL_BREEDING_AGAIN = 15;
22	    private static final int GRASS_FOOD_VALUE = 19;
23	    private static final double MAX_FOOD_LEVEL = 28;
24	    private static final double GROWTH_RATE = 0.015;
25	
26	    // Individual characteristics (instance fields).
27	    private HashMap<Class<? extends Actor>, Integer> food;
28	
29	    /**
30	     * Create a new Zebra. A Zebra may be created with age
31	     * zero (a new born) or with a random age.
32	     *
33	     * @param randomAge If true, the Zebra will have a random age and hunger level.
34	     * @param field The field currently occupied.
35	     * @param location The location within the field.
36	     */
37	    public Zebra(boolean randomAge, Field field, Location location)
38	    {
39	        super(field, location);
