7	 * Grass age, breed and die.
8	 *
9	 * @version 2022.03.01
10	 */
11	public class Grass extends Plants
12	{
13	    // The age at which a grass plant can start to grow.
14	    private static final int BREEDING_AGE = 1;
15	    // The age to which a grass plant can live.
16	    private static final int MAX_AGE = 200;
17	    // The maximum number of sqaures new grass can grow into.
18	    private static final int MAX_LITTER_SIZE = 500;
19	
20	    /**
21	     * Create a new grass plant at location in field.
22	     *
23	     * @param randomAge True if a random age should be generated for the grass
24	     * @param field The field currently occupied.
25	     * @param location The location within the field.
26	     */
27	    public Grass(boolean randomAge, Field field, Location location)
28	    {
29	        super(field, location);
30	        setAge(0);
31	        if(randomAge) {
32	            setAge(getRandom().nextInt(MAX_AGE));
33	        } 
34	        setGrowthLevel(getAge()/50.0);
35	    }
36	
37	    /**
38	     * Make this plant act - that is: make it do
39	     * whatever it wants/needs to do.
40	     * 
41	     * @param newGrass A list to receive newly born grass.
42	     * @param simulator The simulator.
43	     */
44	    public void act(List<Actor> newGrass,Simulator simulator){
45	        incrementAge(simulator.getSteps());
46	        setGrowthLevel(0.05);
47	        if(simulator.isDay()){
48	            if(isActive()) {
49	                 Field field = getField();
50	                //sets the location to show the grass once the actor on top of it has moved.
51	                if (field.getObjectAt(getLocation()) == null ){
52	                    setLocation(getLocation());
53	                }else if (field.getObjectAt(getLocation()) != this && (field.getObjectAt(getLocation()) instanceof Plants)){
54	                    Object grassObject = field.getObjectAt(getLocation());
55	                    Plants grassPlant = (Plants)grassObject;
56	                    grassPlant.setDead();
57	                    setLocation(getLocation());
58	
59	                }
60	                
61	                switch(simulator.getWeather()){
62	                    case SUNNY:
63	                        increaseSunLevel();
64	                        decreaseWaterLevel();
65	                        break;
66	                    case RAINY:
67	                        increaseWaterLevel();
68	                        decreaseSunLevel();
69	                        break;
70	                    case FOGGY:
71	                        increaseWaterLevel();
72	                        break;
73	                    default:
74	                        break;
75	                }
76	                List<Location> free = field.getFreeAdjacentLocations(getLocation());
77	                int births = growth(simulator.getSteps());
78	                for(int b = 0; b < births && free.size() > 0; b++) {
79	                    Location loc = free.remove(0);
80	                    Grass young = new Grass(false, field, loc);
81	                    newGrass.add(young);
82	                }
83	            }  
84	        }else{
85	            //space for potential night activities
86	        }
87	    }
