30	     */
31	    protected int growth(int step)
32	    {
33	        int births = 0;
34	        if(getAge() >= getBreedingAge() && getAge() % 2 == 0 ) {
35	            births = getRandom().nextInt(getMaxLitter()) + 1;
36	        }
37	        
38	        if(step > 1600){
39	            births = births + 20;
40	        }
