1	import java.util.Random;
2	import java.util.List;
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.awt.Color;
6	
7	/**
8	 * A simple predator-prey simulator of a safari, based on a rectangular field
9	 * containing lions, cheetahs, jaguars, zebras, gazelles, hunters and grass.
10	 *
11	 * @version 2022.03.01
12	 */
13	public class Simulator
14	{
15	    // Constants representing configuration information for the simulation.
16	    // The default width for the grid.
17	    private static final int DEFAULT_WIDTH = 175;
18	    // The default depth of the grid.
19	    private static final int DEFAULT_DEPTH = 150;
20	
21	    // The probability that each actor will be created in any given grid position.
22	    private static final double JAGUAR_CREATION_PROBABILITY = 0.011; 
23	    private static final double GAZELLE_CREATION_PROBABILITY = 0.2;
24	    private static final double LION_CREATION_PROBABILITY = 0.017 ; 
25	    private static final double PLANT_CREATION_PROBABILITY = 0.55; 
26	    private static final double CHEETAH_CREATION_PROBABILITY =0.032;
27	    private static final double ZEBRA_CREATION_PROBABILITY = 0.4998; 
28	    private static final double HUNTER_CREATION_PROBABILITY = 0.01; 
29	
30	    // List of animals and plants which can not be stood on in the field.
31	    private List<Actor> animals;
32	    // List of plants that can be stood on in the field.
33	    private List<Actor> plants;
34	    // The current state of the field.
35	    private Field field;
36	    // The current step of the simulation.
37	    private int step;
38	    // A graphical view of the simulation.
39	    private SimulatorView view;
40	
41	    private boolean isDay;
42	    //check the random weather method and the use of the random weather method in one step method
43	    private Weather weather;
44	    private int numberOfDays;
45	    private static final Random rand = Randomizer.getRandom();
46	    private int noOfGrass; // keeps count of the no.of grass species in the field.
47	    /**
48	     * Construct a simulation field with default size.
49	     */
50	    public Simulator()
51	    {
52	        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
53	    }
54	
55	    /**
56	     * Create a simulation field with the given size.
57	     * @param depth Depth of the field. Must be greater than zero.
58	     * @param width Width of the field. Must be greater than zero.
59	     */
60	    public Simulator(int depth, int width)
61	    {
62	        if(width <= 0 || depth <= 0) {
63	            System.out.println("The dimensions must be greater than zero.");
64	            System.out.println("Using default values.");
65	            depth = DEFAULT_DEPTH;
66	            width = DEFAULT_WIDTH;
67	        }
68	
69	        animals = new ArrayList<>();
70	        plants = new ArrayList<>();
71	        field = new Field(depth, width);
72	
73	        // Create a view of the state of each location in the field.
74	        view = new SimulatorView(depth, width, this);
75	        view.setColor(Gazelle.class, Color.ORANGE);
76	        view.setColor(Jaguar.class, Color.BLUE);
77	        view.setColor(Cheetah.class, Color.RED);
78	        view.setColor(Lion.class, Color.PINK);
79	        view.setColor(Grass.class, Color.GREEN);
80	        view.setColor(Zebra.class, Color.BLACK);
81	        view.setColor(Hunter.class, Color.MAGENTA);
82	        // Setup a valid starting point.
83	        reset();
84	    }
85	
86	    /**
87	     * Run the simulation from its current state for a reasonably long period,
88	     * (4000 steps).
89	     */
90	    public void runLongSimulation()
91	    {
92	        simulate(4000);
93	    }
94	
95	    /**
96	     * Run the simulation from its current state for the given number of steps.
97	     * Stop before the given number of steps if it ceases to be viable.
98	     * @param numSteps The number of steps to run for.
99	     */
100	    public void simulate(int numSteps)
101	    {
102	        for(int step = 1; step <= numSteps && view.isViable(field); step++) {
103	            simulateOneStep();
104	        }
105	    }
106	
107	    /**
108	     * Run the simulation from its current state for a single step.
109	     * Iterate over the whole field updating the state of each
110	     * actor in the field. One  day lasts 4 steps, with day and night alternating every 2 steps.
111	     * Buttons are disabled before the simulation starts and enabled after the simulation is finsihed.
112	     */
113	    public void simulateOneStep()
114	    {
115	        view.disableButton();
116	        step++;
117	        if(step % 2 == 0){
118	            isDay  = !isDay;
119	            if(isDay){
120	                numberOfDays++;
121	            }
122	        }
123	
124	        // Provide space for newborn actors.
125	        List<Actor> newAnimals = new ArrayList<>();  
126	        List<Actor> newGrass = new ArrayList<>();  
127	
128	        getRandomWeather();
129	        while(!isDay && weather == Weather.SUNNY){
130	            getRandomWeather();
131	        }
132	        // Let all actors act.
133	        //iterates through all the animals and hunters
134	
135	        for(Iterator<Actor> it = animals.iterator(); it.hasNext(); ) {
136	            Actor animal = it.next();
137	            animal.act(newAnimals,this);
138	            if(! animal.isActive()) {
139	                it.remove();
140	            }
141	        }
142	        animals.addAll(newAnimals);
143	        noOfGrass = 0;
144	        for(Iterator<Actor> it = plants.iterator(); it.hasNext(); ) {
145	            Actor plants = it.next();
146	            plants.act(newGrass,this);
147	            if(! plants.isActive()) {
148	                it.remove();
149	            }else if(plants instanceof Plants){
150	                noOfGrass++;
151	            }
152	        }
153	        plants.addAll(newGrass);
154	
155	        if(step % 500 == 0){
156	            introduceInfection();
157	        }
158	
159	        view.showStatus(field);
160	        view.enableButton();
161	    }
162	
163	    /**
164	     * Reset the simulation to a starting position.
165	     */
166	    public void reset()
167	    {
168	        step = 0;
169	        animals.clear();
170	        plants.clear();
171	        populate();
172	        isDay = true;
173	        numberOfDays = 0;
174	        getRandomWeather();
175	        // Show the starting state in the view.
176	        view.showStatus(field);
177	    }
178	
179	    /**
180	     * Randomly populate the field with all the actors.
181	     */
182	    private void populate()
183	    {
184	        field.clear();
185	        for(int row = 0; row < field.getDepth(); row++) {
186	            for(int col = 0; col < field.getWidth(); col++) {
187	                if(rand.nextDouble() <= LION_CREATION_PROBABILITY) {
188	                    Location location = new Location(row, col);
189	                    Animal lion = new Lion(true, field, location);
190	                    animals.add(lion);
191	                }
192	                else if(rand.nextDouble() <= CHEETAH_CREATION_PROBABILITY) {
193	                    Location location = new Location(row, col);
194	                    Animal cheetah = new Cheetah(true, field, location);
195	                    animals.add(cheetah);
196	                }
197	                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
198	                    Location location = new Location(row, col);
199	                    Animal gazelle = new Gazelle(true, field, location);
200	                    animals.add(gazelle);
201	                }else if(rand.nextDouble() <= JAGUAR_CREATION_PROBABILITY) {
202	                    Location location = new Location(row, col);
203	                    Animal jaguar = new Jaguar(true, field, location);
204	                    animals.add(jaguar);
205	                }else if(rand.nextDouble() <= PLANT_CREATION_PROBABILITY) {
206	                    Location location = new Location(row, col);
207	                    Plants grass = new Grass(true, field, location);
208	                    plants.add(grass);
209	                }
210	                else if(rand.nextDouble() <= ZEBRA_CREATION_PROBABILITY) {
211	                    Location location = new Location(row, col);
212	                    Animal zebra = new Zebra(true, field, location);
213	                    animals.add(zebra);
214	                }else if(rand.nextDouble() <= HUNTER_CREATION_PROBABILITY) {
215	                    Location location = new Location(row, col);
216	                    Hunter hunter = new Hunter(field, location);
217	                    animals.add(hunter);
218	                }
219	                // else leave the location empty.
220	            }
221	        }
222	    }
223	
224	    /**
225	     * Return the total number of steps the simulation has run for.
226	     * @return The total steps the simualtion ran for.
227	     */
228	    public int getSteps(){
229	        return step;
230	    }
231	
232	    /**
233	     * Randomly generates a weather from the enum class.
234	     * @return A random weather.
235	     */
236	    private void getRandomWeather(){
237	        int value = rand.nextInt(weather.values().length);
238	        weather = weather.values()[value];
239	    }
240	
241	    /**
242	     * Returns the List which contains all the plants in the simualtion.
243	     * @return A list of all the alive plants in the simulation.
244	     */
245	    public List<Actor> getGrass(){
246	        return plants;
247	    }  
248	
249	    /**
250	     * Chooses a random animal to infect. This method is automatically called after 100 steps,
251	     * or it can be called by pressing the introduce infection button.
252	     */
253	    public void introduceInfection(){
254	        if(animals.size() != 0){
255	            int value = rand.nextInt(animals.size());
256	            if(animals.get(value) instanceof Animal){
257	                Animal animal = (Animal)animals.get(value);
258	                animal.setUnhealthy();
259	            }
260	        }
261	    }
262	    
263	    /**
264	     * Returns the number of grass in the plants arrayList.
265	     * @return number of grass in arraylist.
266	     */
267	    public int getNoOfGrass(){
268	        return noOfGrass;
269	    }
270	    
271	    /**
272	     * Returns the number of days.
273	     * @return  number of days.
274	     */
275	    public int  getNoOfDays(){
276	        return numberOfDays;
277	    }
278	    
279	    /**
280	     * Returns if it is currently day or night.
281	     * @return true if it is day.
282	     */
283	    public boolean  isDay(){
284	        return isDay;
285	    }
286	    
287	    /**
288	     * Return the weather in the simulation.
289	     * @return weather The current weather in the simulation.
290	     */
291	    public Weather getWeather(){
292	        return weather;
293	    }
294	}
