2	import java.awt.Color;
3	import java.util.HashMap;
4	
5	/**
6	 * This class collects and provides some statistical data on the state 
7	 * of a field. It is flexible: it will create and maintain a counter 
8	 * for any class of object that is found within the field.
9	 *
10	 * @version 2022.03.01
11	 */
12	public class FieldStats
13	{
14	    // Counters for each type of entity (jaguar, gazelle, etc.) in the simulation.
15	    private HashMap<Class, Counter> counters;
16	    // Whether the counters are currently up to date.
17	    private boolean countsValid;
18	
19	    /**
20	     * Construct a FieldStats object.
21	     */
22	    public FieldStats()
23	    {
24	        // Set up a collection for counters for each type of animal that
25	        // we might find
26	        counters = new HashMap<>();
27	        countsValid = true;
28	    }
29	
30	    /**
31	     * Get details of what is in the field.
32	     * @param field The field currently occupied.
33	     * @param simulator. The current simulator the simulation is being run on.
34	     * @return A string listing what is in the field.
35	     */
36	    public String getPopulationDetails(Field field, Simulator simulator)
37	    {
38	        StringBuffer buffer = new StringBuffer();
39	        if(!countsValid) {
40	            generateCounts(field, simulator);
41	        }
42	        for(Class key : counters.keySet()) {
43	            Counter info = counters.get(key);
44	            buffer.append(info.getName());
45	            buffer.append(": ");
46	            buffer.append(info.getCount());
47	            buffer.append(' ');
48	        }
49	        return buffer.toString();
50	    }
51	
52	    /**
53	     * Invalidate the current set of statistics; reset all 
54	     * counts to zero.
55	     */
56	    public void reset()
57	    {
58	        countsValid = false;
59	        for(Class key : counters.keySet()) {
60	            Counter count = counters.get(key);
61	            count.reset();
62	        }
63	    }
64	
65	    /**
66	     * Increment the count for one class of actor.
67	     * @param actor The object of animal to increment.
68	     * @param simulator. The current simulator the simulation is being run on.
69	     */
70	    public void incrementCount(Object actor, Simulator simulator)
71	    {
72	        Class animalClass = actor.getClass();
73	        Counter count = counters.get(animalClass);
74	        if(count == null) {
75	            // We do not have a counter for this species yet.
76	            // Create one.
77	            count = new Counter(animalClass.getName());
78	            counters.put(animalClass, count);
79	        }
80	        count.increment();
81	        if (simulator.getSteps() != 0){
82	            if(actor instanceof Grass){
83	                count.setCount(simulator.getNoOfGrass());
84	            }
85	        }
86	    }
87	
88	    /**
89	     * Indicate that an actor count has been completed.
90	     */
91	    public void countFinished()
92	    {
93	        countsValid = true;
94	    }
95	
96	    /**
97	     * Determine whether the simulation is still viable.
98	     * I.e., should it continue to run.
99	     * @param field The field currently occupied.
100	     * @param simulator The current simulator the simulation is being run on.
101	     * @return true If there is more than one species alive.
102	     */
103	    public boolean isViable(Field field, Simulator simulator)
104	    {
105	        // How many counts are non-zero.
106	        int nonZero = 0;
107	        if(!countsValid) {
108	            generateCounts(field, simulator);
109	        }
110	        for(Class key : counters.keySet()) {
111	            Counter info = counters.get(key);
112	            if(info.getCount() > 0) {
113	                nonZero++;
114	            }
115	        }
116	        return nonZero > 1;
117	    }
118	
119	    /**
120	     * Generate counts of the number of all animals.
121	     * These are not kept up to date as all animals
122	     * are placed in the field, but only when a request
123	     * is made for the information.
124	     * @param field The field to generate the stats for.
125	     * @param simulator The current simulator the simulation is being run on.
126	     */
127	    private void generateCounts(Field field, Simulator simulator)
128	    {
129	        reset();
130	        for(int row = 0; row < field.getDepth(); row++) {
131	            for(int col = 0; col < field.getWidth(); col++) {
132	                Object animal = field.getObjectAt(row, col);
133	                if(animal != null) {
134	                    incrementCount(animal, simulator);
135	                }
136	            }
137	        }
138	        countsValid = true;
139	    }
140	}
